UPDATE public.flashcards SET cloze_text = $px${{c1::Hund's rule}} states that within a degenerate subshell (e.g., the three p orbitals), electrons singly occupy separate orbitals with {{c2::parallel spins}} before any orbital is doubly filled — an arrangement that minimizes electron-electron repulsion.$px$ WHERE id = '0030e905-e7b7-48fb-ae5b-03652df2913f';
UPDATE public.flashcards SET cloze_text = $px$A worker paid per dozen items assembled is on a {{c1::fixed-ratio}} schedule, whereas a slot-machine gambler is on a {{c1::variable-ratio}} schedule — the most resistant to {{c2::extinction}}.$px$ WHERE id = '00936388-f31a-4d00-a388-13102bdbde64';
UPDATE public.flashcards SET cloze_text = $px$The {{c1::periodic law}} states that the chemical and physical properties of the elements are a {{c1::periodic}} function of their {{c2::atomic numbers}} — as Z increases, certain properties recur at regular intervals corresponding to the underlying electronic structure.$px$ WHERE id = '00bd9c05-b7e9-4d9a-9921-10f387db7ee6';
UPDATE public.flashcards SET cloze_text = $px${{c1::Extremophiles}} — organisms that thrive in extreme temperature, salinity, pH, or anoxic environments — are disproportionately drawn from the domain {{c2::Archaea}}.$px$ WHERE id = '00cd9a69-ac90-4c3b-934b-a988fa11ecf1';
UPDATE public.flashcards SET cloze_text = $px$In metabolic acidosis, respiratory rate increases to {{c1::blow off CO₂}}, shifting the bicarbonate equilibrium {{c2::left}} and reducing free H⁺ — a respiratory compensation for the pH drop.$px$ WHERE id = '00f3d843-1de8-4363-a89b-16de6e70b3c8';
UPDATE public.flashcards SET cloze_text = $px${{c1::Inclusive fitness}} measures reproductive success as the sum of an organism's {{c2::own offspring}} plus the offspring of {{c3::relatives}} that share its genes — explaining why altruism toward kin is favored.$px$ WHERE id = '020f188d-f362-491a-bdf6-4e9a54ccf31b';
