UPDATE public.flashcards SET cloze_text = $px$The SN1 carbocation intermediate is {{c1::planar (sp²)}}, so the nucleophile can attack from either face — the product is typically a {{c2::racemic mixture}}.$px$ WHERE id = '02c87afe-7521-475c-8b37-44219930e81e';
UPDATE public.flashcards SET cloze_text = $px$For molecules of the same chain length, boiling points rank {{c1::alcohol > carbonyl > alkane}} — {{c1::alcohols}} can {{c2::hydrogen bond}}, {{c1::carbonyls}} have {{c3::dipole–dipole interactions only}}, and {{c1::alkanes}} have only van der Waals forces.$px$ WHERE id = '0310c7b1-1936-41d3-b855-2d292e2a6ea5';
UPDATE public.flashcards SET cloze_text = $px$In a complex ion, the central metal ion is the Lewis {{c1::acid}} — the electron-pair {{c1::acceptor}} in each coordinate covalent bond.$px$ WHERE id = '039e3d7b-0f4c-4e59-a0e4-258592fb64f5';
UPDATE public.flashcards SET cloze_text = $px${{c1::Nondisjunction}} — the failure of homologs (meiosis I) or sister chromatids (meiosis II or mitosis) to separate properly — produces gametes or cells with abnormal chromosome counts, a condition called {{c2::aneuploidy}}.$px$ WHERE id = '03fe67e6-d7ad-4aff-a39d-35c7b90e568f';
UPDATE public.flashcards SET cloze_text = $px$Gas exchange happens in the {{c1::alveoli}} — clusters of tiny, grape-like sacs budding off the alveolar ducts at the tips of the bronchiole tree; because so many crowd the lungs, their walls together present a respiratory surface of roughly {{c2::70}} square meters.$px$ WHERE id = '040395fd-8801-44ee-85ae-8fce6793e6a3';
UPDATE public.flashcards SET cloze_text = $px$Within a eukaryotic cell, {{c1::cilia}} sweep extracellular material across a stationary cell surface, while {{c1::flagella}} propel the cell itself through its environment — the same architecture deployed for two distinct jobs.$px$ WHERE id = '041a56d5-7e50-4c1b-a26f-68a442db647b';
UPDATE public.flashcards SET cloze_text = $px$A {{c1::catalyst}} accelerates a reaction yet is {{c2::not consumed}} overall — it is {{c2::regenerated}} in a later step, so it can turn over many reactant molecules.$px$ WHERE id = '045131e5-d814-4c4c-b479-324165cc6a3e';
UPDATE public.flashcards SET cloze_text = $px${{c1::Valence electrons}} are those in the outermost energy shell — the electrons most loosely bound, most easily removed, and {{c2::available for chemical bonding}}. They dominate the chemical behavior of the element.$px$ WHERE id = '04a79679-8cf4-4909-9410-181ac4df8c0d';
UPDATE public.flashcards SET cloze_text = $px${{c1::Temperament}} — an innate, biologically based disposition that appears very early in infancy — provides the foundation later shaped into adult personality.$px$ WHERE id = '04b54895-8f53-491a-8be1-c3dd6e6db32f';
