UPDATE public.flashcards SET cloze_text = $px${{c1::LiAlH₄}} is a strong reducing agent that handles carboxylic acids, esters, amides, plus {{c3::aldehydes and ketones}}; {{c2::NaBH₄}} is milder — useful when you want to reduce only {{c3::aldehydes or ketones}} and leave other functional groups intact.$px$ WHERE id = '05a4ca1a-5ad6-412f-ad0d-fd86f308bf62';
UPDATE public.flashcards SET cloze_text = $px$The {{c1::hypothalamus}} is small but functionally critical — it maintains {{c2::homeostasis}}, regulates the autonomic nervous system, and drives basic behaviors such as hunger, thirst, sexual behavior, and aggression.$px$ WHERE id = '05ccf373-c6bb-410c-9ac4-8e9c5b6ef8e8';
UPDATE public.flashcards SET cloze_text = $px$The {{c1::role partner}} is the other person a role is directed toward — for instance, a teacher's role toward students, or a doctor's toward patients.$px$ WHERE id = '062a0bc2-c82d-4b88-9547-1d7da77adebb';
UPDATE public.flashcards SET cloze_text = $px$A {{c1::non-conservative force}} is one whose work is {{c2::path-dependent}} — more work is required along a longer route than a shorter one between the same two endpoints. {{c1::Non-conservative forces}} {{c3::dissipate}} mechanical energy, usually converting it to heat.$px$ WHERE id = '0672961b-50e4-4c75-89d1-381977881f8b';
UPDATE public.flashcards SET cloze_text = $px$The {{c1::A elements}} (groups 1A–8A) are called {{c2::representative elements}}; the {{c3::B elements}} include the transition metals plus the lanthanide and actinide series and are called {{c4::non-representative elements}}.$px$ WHERE id = '07eadafd-f15e-4880-b269-d7a155ceb2c7';
UPDATE public.flashcards SET cloze_text = $px$Whatever debris slips past the nose and mouth meets the trachea and bronchi, whose {{c1::pseudostratified ciliated columnar}} epithelium (studded with mucus-secreting goblet cells) forms a {{c2::mucociliary escalator}} — its cilia beat in unison to drive trapped particles upward toward the throat to be swallowed.$px$ WHERE id = '07fd5257-fd49-488f-a41a-cb457c735750';
