UPDATE public.flashcards SET cloze_text = $px$The two hormones stored and released by the posterior pituitary are {{c1::antidiuretic hormone (ADH, also called vasopressin)}} — which promotes water retention — and {{c2::oxytocin}} — which drives uterine contractions during labor and milk letdown during nursing.$px$ WHERE id = '0eda0590-f9fc-4b70-897b-e245771d3412';
