UPDATE public.flashcards SET cloze_text = $px${{c1::Bottom-up (data-driven)}} processing constructs perceptions starting from raw sensory features — analyzing individual stimuli and combining them into a whole. It is {{c2::slower but more accurate}}, and it is required when the stimulus is novel or unfamiliar.$px$ WHERE id = '12057c24-73db-4160-84df-1a0360f156a2';
