UPDATE public.flashcards SET cloze_text = $px$Electronegativity {{c1::increases}} from left to right across a period and {{c2::decreases}} from top to bottom in a group — the same direction pattern as ionization energy.$px$ WHERE id = '13281a26-cee4-432d-b74b-b7cb25a6a42c';
