UPDATE public.flashcards SET cloze_text = $px$Once R/S has been assigned, the descriptor is written in {{c1::parentheses with a hyphen}} preceding the rest of the name — for example, {{c2::(R)-2-bromobutane}}, and {{c2::(2S,3R)-3-bromo-2-butanol}} for a molecule with multiple chiral centers labeled by locant.$px$ WHERE id = '13cee5eb-1991-464a-a352-4973603c99ee';
UPDATE public.flashcards SET cloze_text = $px${{c1::SN1}} (unimolecular nucleophilic substitution) is a {{c2::two-step}} reaction: Step 1 ({{c3::rate-limiting}}) — leaving group departs to form a {{c4::carbocation}}; Step 2 — nucleophile attacks the {{c4::carbocation}}.$px$ WHERE id = '13dd27d1-8095-43ad-8aac-0031f7e81439';
