UPDATE public.flashcards SET cloze_text = $px$The {{c1::octet rule}} states that atoms tend to bond so that each ends up with {{c2::8}} valence electrons — the stable electron configuration of a noble gas.$px$ WHERE id = '15d10c23-8dcc-43fd-8e40-c3e48adea169';
UPDATE public.flashcards SET cloze_text = $px${{c1::Pacinian corpuscles}} are large, deep-skin mechanoreceptors with a distinctive onion-like layered structure. They specialize for {{c2::deep pressure and high-frequency vibration}} and are rapidly adapting — they respond to changes in pressure but stop firing under sustained pressure.$px$ WHERE id = '16381a09-73db-4678-8b5c-abdfa3d7c836';
UPDATE public.flashcards SET cloze_text = $px$In the solid state, ionic compounds form a {{c1::crystalline lattice}} of alternating positive and negative ions — geometry that {{c2::maximizes}} attraction between opposite charges and {{c2::minimizes}} repulsion between like charges.$px$ WHERE id = '16b509b6-55aa-4dde-a3ed-8c0e51dd50f2';
UPDATE public.flashcards SET cloze_text = $px$When blood calcium falls, the {{c1::parathyroid}} glands release {{c1::parathyroid hormone (PTH)}}, which {{c2::raises}} circulating calcium — directly opposing the thyroid hormone {{c3::calcitonin}}, its physiological antagonist that lowers calcium.$px$ WHERE id = '16f66da1-e4c4-4fd8-a756-ef804f0a5420';
UPDATE public.flashcards SET cloze_text = $px$Prompted by pituitary {{c1::gonadotropins}} (LH and FSH), the ovaries release {{c2::estrogens}} and {{c2::progesterone}} — the hormones that steer female reproductive development and the {{c3::secondary sex characteristics}}.$px$ WHERE id = '175434fa-11cf-4397-a9c9-607306fe43fc';
UPDATE public.flashcards SET cloze_text = $px${{c1::Epinephrine}} requires thyroid hormone to exert its full metabolic effect — without sufficient T₃/T₄, catecholamines lose much of their metabolic punch.$px$ WHERE id = '17abe67c-936c-470e-be0a-c668a68a8ebd';
UPDATE public.flashcards SET cloze_text = $px$At the alveolus during external respiration, O₂ travels {{c1::from air into the blood}} while CO₂ travels {{c2::from the blood into the air}} — the two gases cross the respiratory membrane in opposite directions because each follows its own {{c3::partial-pressure gradient}} (alveolar PO₂ ~104 vs. capillary ~40 mm Hg; capillary PCO₂ ~45 vs. alveolar ~40 mm Hg).$px$ WHERE id = '181a6cf9-7860-49c1-96da-8db2e1b36f8e';
UPDATE public.flashcards SET cloze_text = $px$Energy is the capacity of a system to {{c1::do work}} or bring about change. Its SI unit is the {{c2::joule (J)}}, which is also the unit of {{c1::work}} — both measure the same physical quantity expressed in base units as {{c3::kg·m²/s²}}.$px$ WHERE id = '184cbb26-087e-4b7c-b402-ed6e0a804585';
UPDATE public.flashcards SET cloze_text = $px$A {{c1::mutagen}} is any agent — radiation (UV, X-rays), chemicals, or certain viruses — that increases the rate of mutation in DNA.$px$ WHERE id = '187997c6-4a72-4f6b-a0d1-cc05619f5c47';
UPDATE public.flashcards SET cloze_text = $px$Because Complex II does not pump protons, electrons that enter via {{c1::FADH₂}} skip Complex I and contribute fewer protons to the gradient — yielding ~{{c2::1.5 ATP}} per {{c1::FADH₂}} vs ~2.5 ATP per NADH.$px$ WHERE id = '18991078-fecc-4022-b90a-5ccbab635a36';
