UPDATE public.flashcards SET cloze_text = $px$After a maximal inhale, the lungs top out at their {{c1::total lung capacity (TLC)}} — roughly {{c2::6 L}} in a typical adult — which you can reconstruct by adding the volume a full exhale expels, {{c3::vital capacity}}, to the air stranded behind it, the {{c4::residual volume}}.$px$ WHERE id = '335fb24e-0689-43bb-a12e-94d1e79bf0c1';
