UPDATE public.flashcards SET cloze_text = $px$Although its resting rhythm is set involuntarily by the {{c1::medulla oblongata}} (an autonomic-style brainstem drive), the diaphragm is histologically {{c2::skeletal muscle}}, so it also answers to {{c3::somatic (voluntary)}} commands from the cerebral cortex — which is exactly how you can consciously hold your breath.$px$ WHERE id = '36fe2965-2b67-417f-9dc8-770af4ecb44e';
