UPDATE public.flashcards SET cloze_text = $px$Because no {{c1::horizontal}} force acts on a projectile (ignoring air resistance), the {{c1::horizontal velocity remains constant}} throughout the flight. Only the {{c2::vertical}} velocity changes — by g (≈ 9.8 m/s²) downward each second.$px$ WHERE id = '3757167c-57e0-4777-9cbe-6c52a4efefd9';
