UPDATE public.flashcards SET cloze_text = $px$The {{c1::proton motive force}} is the electrochemical gradient across the inner mitochondrial membrane — a combination of a {{c2::pH}} gradient (chemical) and a charge difference (electrical) — built up by ETC proton pumping.$px$ WHERE id = '388537f0-bfc3-4b17-911c-9f3470e99c2e';
