UPDATE public.flashcards SET cloze_text = $px$Pulmonary mast cells arm themselves with surface-bound {{c1::IgE}}, which docks via its Fc region to an IgE-specific Fc receptor; an inhaled allergen crosslinks these antibodies, driving {{c2::degranulation}} that discharges {{c3::histamine}} and other inflammatory mediators — the immediate (Type I) hypersensitivity that underlies allergic asthma.$px$ WHERE id = '39d6a5fb-96c7-4577-b828-3373fa805007';
UPDATE public.flashcards SET cloze_text = $px${{c1::Paul Broca}} was the first to demonstrate that a specific functional impairment could be linked to a specific {{c2::brain lesion}}. He studied a patient who could not produce speech and traced the deficit to damage in a left-hemisphere region of the frontal lobe — now known as {{c3::Broca's area}}.$px$ WHERE id = '3a2e09de-cd3e-4804-8f90-a819e77724ca';
