UPDATE public.flashcards SET cloze_text = $px$The SI unit of work is the {{c1::joule (J)}}, defined as one newton-meter (1 J = 1 N·m). In base units, 1 J = {{c2::kg·m²/s²}} — identical to the SI unit of energy, since work is simply energy in transit.$px$ WHERE id = '3ae3d628-9fb2-44b6-a726-73df3fec61d5';
