UPDATE public.flashcards SET cloze_text = $px$On a planet, the weight of an object is given by {{c1::W = mg}}, where m is the object's mass and g is the {{c2::local acceleration due to gravity}} (≈ 9.8 m/s² on Earth's surface). Note: lowercase g is {{c2::acceleration}}; uppercase G is the universal gravitational constant — they are different quantities.$px$ WHERE id = '3d1ef3c2-2897-4e93-8371-7b515573baaf';
UPDATE public.flashcards SET cloze_text = $px$Polar, acidic, and basic amino acids are {{c1::hydrophilic}} — they tend to be found on protein surfaces, where they form {{c2::hydrogen bonds}} with surrounding water.$px$ WHERE id = '3e23a2e6-b642-4734-8e4a-bfebf0cec887';
