UPDATE public.flashcards SET cloze_text = $px${{c1::Social capital}} is the investment people make in society in return for {{c2::economic or collective rewards}}; greater investment leads to higher {{c3::social integration}} — the incorporation of new groups while they maintain their identities.$px$ WHERE id = '400cd46d-5717-4c7c-9883-0853ab666d1c';
UPDATE public.flashcards SET cloze_text = $px$Because the resting diaphragm sits as a {{c1::dome}}, its contraction pulls the muscle {{c2::downward (inferiorly), flattening it}} — enlarging the thoracic cavity to draw air in — while relaxation lets it recoil back up into that {{c1::dome}} shape during quiet expiration.$px$ WHERE id = '40bc34df-84d4-458c-8061-ac0376059bf9';
UPDATE public.flashcards SET cloze_text = $px$When a force has a component {{c1::parallel}} to the displacement, the work it does is {{c2::positive}} — the force adds energy to the object. When it has a component {{c1::antiparallel}} to the displacement (like friction during forward motion), the work is {{c2::negative}} — the force removes energy.$px$ WHERE id = '417fd6a1-67b6-4cd3-bfbb-8a24e3d0d36d';
