UPDATE public.flashcards SET cloze_text = $px$A {{c1::critical period}} is a developmental window during which the nervous system is especially {{c2::susceptible to environmental input}}. Skills or traits not acquired during the {{c1::critical period}} may be difficult or impossible to acquire later — language acquisition is the canonical example.$px$ WHERE id = '42fd933d-7825-4b03-bbc1-63cc41089aba';
