UPDATE public.flashcards SET cloze_text = $px$Peptide bonds are cleaved by {{c1::hydrolysis}} — adding a water molecule across the bond to release free amino acids; this is catalyzed by strong acid, strong base, or {{c2::proteolytic enzymes}}.$px$ WHERE id = '44091036-13a6-4c00-bfd7-cfe207ee47cc';
UPDATE public.flashcards SET cloze_text = $px$In any circular motion, the net inward force is called the {{c1::centripetal force}}. This is not a separate kind of force — it is whatever actual force (gravity, tension, normal, friction, electromagnetic) happens to be directed toward the center of the circle. Its magnitude is {{c2::Fc = mv²/r}}.$px$ WHERE id = '4409b4f7-ed23-4b80-8ee0-00021ee2e1c6';
