UPDATE public.flashcards SET cloze_text = $px$In the airway, goblet cells secrete a mucus layer that captures inhaled dust and pathogens, while the beating cilia beneath it drive that debris-laden sheet upward toward the pharynx — a clearance mechanism termed the {{c1::mucociliary escalator}}, whose trapped load is ultimately {{c2::swallowed}} into the acidic stomach.$px$ WHERE id = '8cebb8f6-a4c4-4773-a63a-efee0707826e';
