UPDATE public.flashcards SET cloze_text = $px$For a {{c1::galvanic}} cell, the species with the more {{c2::positive}} reduction potential is reduced — it serves as the cathode; the other species is oxidized at the anode.$px$ WHERE id = '9031dc3d-d199-49ab-9ef0-d26776f70306';
