UPDATE public.flashcards SET cloze_text = $px${{c1::Vitamin K₁ (phylloquinone)}} is found in {{c2::green leafy vegetables}}; {{c1::Vitamin K₂ (menaquinone)}} is produced by {{c2::gut bacteria}} — both are quinones essential for {{c3::blood clotting and bone health}}.$px$ WHERE id = 'c360019c-e1ab-46e0-9852-1cd030a1284a';
UPDATE public.flashcards SET cloze_text = $px$Citric acid cycle — Step 6: {{c1::succinate dehydrogenase}} oxidizes {{c1::succinate}} to fumarate using {{c2::FAD}} (not NAD⁺) — this is the only TCA enzyme embedded in the {{c3::inner mitochondrial membrane}} and is the same as ETC Complex II.$px$ WHERE id = 'c3ea7216-f481-4eee-b00a-c5b2ade8426d';
UPDATE public.flashcards SET cloze_text = $px$Without O₂, the ETC cannot turn over, NADH and FADH₂ accumulate, and the {{c1::citric acid cycle}} stalls — known as respiratory control; ADP and {{c2::NAD⁺}} (not NADH) promote TCA when energy demand rises.$px$ WHERE id = 'c45d787b-2b78-4102-840b-2f39c7ea8119';
UPDATE public.flashcards SET cloze_text = $px$Because flat {{c1::type I alveolar cells}} tile the alveolar wall as a layer just {{c2::one cell}} thick, an O₂ or CO₂ molecule crosses the respiratory membrane by traversing a barrier only ~{{c3::0.5 μm}} deep — the short {{c4::diffusion distance}} that lets simple diffusion keep pace with gas exchange.$px$ WHERE id = 'c521d64b-d34e-47de-be9f-a3a1395740ca';
UPDATE public.flashcards SET cloze_text = $px${{c1::Innate}} behaviors are genetically programmed and appear in all members of a species regardless of environment or experience. {{c2::Learned}} behaviors are not based on heredity — they emerge through experience and interaction with the environment.$px$ WHERE id = 'c63cbd8c-fe04-48c2-b16d-9fc72b2a4db4';
