UPDATE public.flashcards SET cloze_text = $px$Conformational isomers are formally classified as stereoisomers, but they are essentially the same molecule sampled at different rotation states — at room temperature, a molecule spends most of its time in its {{c1::lowest-energy}} conformation and only briefly visits higher-energy ones.$px$ WHERE id = 'c92b0de0-db9f-440f-869f-e7eeb5a5e8a7';
