UPDATE public.flashcards SET cloze_text = $px$A {{c1::physical property}} can be observed or measured without changing its composition (melting point, boiling point, density, solubility, color, odor). A {{c2::chemical property}} describes how a substance {{c3::reacts}} with other species — by definition, observing it changes the composition.$px$ WHERE id = 'ca5ce960-5ed3-444f-b5c3-7f7c78e0ae83';
