UPDATE public.flashcards SET cloze_text = $px$The {{c1::two-point threshold}} is the minimum distance between two points of skin contact such that they can be felt as {{c2::two distinct stimuli}} rather than one. The threshold varies enormously across the body — fingertips have very small {{c1::two-point thresholds}} (high acuity), while the back has very large ones.$px$ WHERE id = 'cb1cb81f-e216-4041-8bd9-116dfdac26a8';
