UPDATE public.flashcards SET cloze_text = $px$The {{c1::atomic weight}} listed on the periodic table is the {{c2::weighted average}} of the masses of an element's naturally occurring isotopes — scaled by relative abundance, which is why most are non-integer values.$px$ WHERE id = 'd1545cf6-7c62-45fd-a421-04e7ac49da33';
